<?php
if (!defined('APP_ENTRY_POINT')) { http_response_code(404); exit; }
$appRoot=dirname(__DIR__,4); if(session_status()===PHP_SESSION_NONE)session_start(); require_once $appRoot.'/auth.php'; checkPermission('manage_members'); require_once $appRoot.'/db_connection.php'; require_once $appRoot.'/app/Core/MemberEncryption.php';
function mhist($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
try{$db=(new Database())->getConnection();$crypto=new MemberEncryption($appRoot);$batches=$db->query('SELECT id,subject_enc,recipient_count,sent_count,failed_count,created_at FROM member_mail_batches ORDER BY created_at DESC,id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);$rows=[];foreach($batches as $b){$b['subject']=$crypto->decrypt($b['subject_enc']);$stmt=$db->prepare('SELECT member_number,recipient_name_enc,recipient_email_enc,send_status,sent_at,error_message FROM member_mail_recipients WHERE batch_id=? ORDER BY id');$stmt->execute([$b['id']]);$b['recipients']=$stmt->fetchAll(PDO::FETCH_ASSOC);foreach($b['recipients'] as &$r){$r['name']=$crypto->decrypt($r['recipient_name_enc']);$r['email']=$crypto->decrypt($r['recipient_email_enc']);}unset($r);$rows[]=$b;}}catch(Throwable $e){error_log('Mitglieder-Versandhistorie: '.$e->getMessage());$error='Die Versandhistorie konnte nicht geladen werden. Bitte Datenbankmigration prüfen.';$rows=[];}
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Versandhistorie – Förderverein intern</title><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="includes/navigation.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><style>.mh-wrap{max-width:1300px;margin:24px auto}.mh-card{background:#fff;border-radius:12px;padding:20px;margin:18px 0;box-shadow:0 2px 12px #0000000d}.mh-table{width:100%;border-collapse:collapse}.mh-table th,.mh-table td{padding:10px;border-bottom:1px solid #e8e8e8;text-align:left}.mh-tag{display:inline-block;padding:3px 8px;border-radius:20px;background:#e8f5e9;color:#246b35;font-size:.82rem}.mh-tag.failed{background:#fdeaea;color:#8b1e1e}.mh-tag.pending{background:#fff3cd;color:#795b00}.mh-details{margin-top:8px}.mh-details summary{cursor:pointer;color:var(--primary-color,#287eaa)}.mh-muted{color:#667085;font-size:.9rem}@media(max-width:700px){.mh-card{padding:12px}.mh-table{font-size:.88rem}}</style></head><body><div class="container"><header class="app-page-header"><h1>Versandhistorie</h1><?php require $appRoot.'/includes/navigation.php';?></header><main class="mh-wrap"><div class="mh-card"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><h2 style="margin:0">Bisherige Versandaufträge</h2><a href="mitglieder_kommunikation.php" class="mh-btn"><i class="fa-solid fa-pen-to-square"></i> Neue E-Mail erstellen</a></div><?php if(!empty($error)):?><p><?=mhist($error)?></p><?php elseif(!$rows):?><p class="mh-muted">Es wurden noch keine E-Mails über die Mitgliederkommunikation versendet.</p><?php else:?><div style="overflow-x:auto"><table class="mh-table"><thead><tr><th>Datum</th><th>Betreff</th><th>Empfänger</th><th>Erfolgreich</th><th>Fehlgeschlagen</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><?=date('d.m.Y H:i',strtotime($b['created_at']))?></td><td><?=mhist($b['subject'])?></td><td><?= (int)$b['recipient_count']?></td><td><?= (int)$b['sent_count']?></td><td><?= (int)$b['failed_count']?></td><td><details class="mh-details"><summary>Empfänger anzeigen</summary><div style="overflow-x:auto"><table class="mh-table"><thead><tr><th>Nr.</th><th>Name</th><th>E-Mail</th><th>Status</th><th>Versandzeit</th><th>Fehler</th></tr></thead><tbody><?php foreach($b['recipients'] as $r):?><tr><td><?= (int)$r['member_number']?></td><td><?=mhist($r['name'])?></td><td><?=mhist($r['email'])?></td><td><span class="mh-tag <?= $r['send_status']==='failed'?'failed':($r['send_status']==='pending'?'pending':'')?>"><?=mhist(['sent'=>'Versendet','failed'=>'Fehlgeschlagen','pending'=>'Ausstehend'][$r['send_status']]??$r['send_status'])?></span></td><td><?= $r['sent_at']?date('d.m.Y H:i',strtotime($r['sent_at'])):'–'?></td><td><?=mhist($r['error_message']??'')?></td></tr><?php endforeach;?></tbody></table></div></details></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></main></div></body></html>
